static inline void __flush_icache_all(void) /* <=== __flush_icache_all */ 
{
	asm("movc	p0.c5, %0, #20;\n"
	    "nop; nop; nop; nop; nop; nop; nop; nop\n"
	    :
	    : "r" (0));
}

